<?php
declare(strict_types=1);
namespace App\BusinessModules\Core\Reporting\Infrastructure\Persistence;
use App\BusinessModules\Core\Reporting\Domain\Contracts\ReportSubscriptionDeliveryStore; use App\BusinessModules\Core\Reporting\Domain\Contracts\ReportSubscriptionStore; use App\BusinessModules\Core\Reporting\Domain\DTO\{ReportSubscription,ReportSubscriptionDelivery}; use App\BusinessModules\Core\Reporting\Domain\Enums\{ReportSubscriptionDeliveryStatus,ReportSubscriptionTrigger}; use App\BusinessModules\Core\Reporting\Domain\ValueObjects\Sha256Hash; use App\BusinessModules\Core\Reporting\Infrastructure\Persistence\Models\ReportSubscriptionDeliveryRecord; use DateTimeImmutable; use DateTimeZone; use Illuminate\Support\Str;
final class EloquentReportSubscriptionDeliveryStore implements ReportSubscriptionDeliveryStore { public function lockWithSubscription(string $id):array{$d=ReportSubscriptionDeliveryRecord::query()->where('id',$id)->lockForUpdate()->firstOrFail();return [$this->dto($d),app(ReportSubscriptionStore::class)->lock($d->subscription_id)];} public function createCalendarScheduledLocked(ReportSubscription $s,DateTimeImmutable $at,string $bytes,Sha256Hash $hash,int $version):ReportSubscriptionDelivery{return $this->dto(ReportSubscriptionDeliveryRecord::query()->create($this->attributes($s,$at,'calendar',$bytes,$hash,$version)));} public function insertManualScheduledOnConflictLocked(ReportSubscription $s,DateTimeImmutable $at,Sha256Hash $key,Sha256Hash $request,string $bytes,Sha256Hash $hash,int $version):?string{$a=$this->attributes($s,$at,'manual',$bytes,$hash,$version)+['trigger_key_hash'=>$key->value,'manual_request_sha256'=>$request->value];$row=ReportSubscriptionDeliveryRecord::query()->insertOrIgnore($a);return $row===1?$a['id']:null;} public function lockManualByScope(string $id,Sha256Hash $key):?ReportSubscriptionDelivery{$r=ReportSubscriptionDeliveryRecord::query()->where('subscription_id',$id)->where('trigger_key_hash',$key->value)->lockForUpdate()->first();return $r?$this->dto($r):null;} public function beginAttemptLocked(ReportSubscriptionDelivery $d):void{$this->move($d,'scheduled',['status'=>'building_run','attempt'=>$d->attempt+1]);} public function attachRunLocked(ReportSubscriptionDelivery $d,string $id):void{$this->move($d,'building_run',['run_id'=>$id]);} public function attachExportLocked(ReportSubscriptionDelivery $d,string $id):void{$this->move($d,'building_run',['status'=>'building_export','export_id'=>$id]);} public function markReadyLocked(ReportSubscriptionDelivery $d):void{$this->move($d,'building_export',['status'=>'ready']);} public function markNotifiedLocked(ReportSubscriptionDelivery $d,string $receipt,Sha256Hash $key):void{$this->move($d,'ready',['status'=>'notified','notification_receipt_id'=>$receipt,'notification_key_hash'=>$key->value,'notified_at'=>now()]);} public function rescheduleRetryLocked(ReportSubscriptionDelivery $d,DateTimeImmutable $at,string $code):void{$this->move($d,$d->status->value,['status'=>'scheduled','retry_at'=>$at,'safe_error_code'=>$code]);} public function markFailedLocked(ReportSubscriptionDelivery $d,string $code):void{$this->move($d,$d->status->value,['status'=>'failed','safe_error_code'=>$code]);} public function expireExecutionsDueLocked(DateTimeImmutable $now,int $limit):array{$rows=ReportSubscriptionDeliveryRecord::query()->whereIn('status',['scheduled','building_run','building_export','ready'])->where('execution_expires_at','<=',$now)->lock('FOR UPDATE SKIP LOCKED')->limit($limit)->get();foreach($rows as $r){$r->status='expired';$r->save();}return $rows->pluck('id')->all();} public function pruneTerminalDueLocked(DateTimeImmutable $now,int $limit):int{$ids=ReportSubscriptionDeliveryRecord::query()->whereIn('status',['notified','failed','expired'])->where('retention_delete_after','<=',$now)->orderBy('id')->limit($limit)->pluck('id');return ReportSubscriptionDeliveryRecord::destroy($ids->all());} private function move(ReportSubscriptionDelivery $d,string $expected,array $changes):void{if(ReportSubscriptionDeliveryRecord::query()->where('id',$d->id)->where('status',$expected)->update($changes)!==1)throw new \LogicException('report_subscription_delivery_concurrent_change');} private function attributes(ReportSubscription $s,DateTimeImmutable $at,string $trigger,string $bytes,Sha256Hash $hash,int $version):array{$n=now();return ['id'=>(string)Str::ulid(),'organization_id'=>$s->organizationId,'owner_id'=>$s->ownerId,'subscription_id'=>$s->id,'trigger'=>$trigger,'scheduled_for'=>$at,'execution_input_bytes'=>$bytes,'execution_input_sha256'=>$hash->value,'subscription_version'=>$version,'status'=>'scheduled','attempt'=>0,'execution_expires_at'=>$at->modify('+86400 seconds'),'retention_delete_after'=>$n->copy()->addDays((int)config('reporting_subscriptions.retention_days')),'created_at'=>$n,'updated_at'=>$n];} private function dto(ReportSubscriptionDeliveryRecord $r):ReportSubscriptionDelivery{$c=fn($v)=>DateTimeImmutable::createFromInterface($v);return new ReportSubscriptionDelivery($r->id,$r->organization_id,$r->owner_id,$r->subscription_id,ReportSubscriptionTrigger::from($r->trigger),$r->trigger_key_hash?new Sha256Hash($r->trigger_key_hash):null,$r->manual_request_sha256?new Sha256Hash($r->manual_request_sha256):null,$c($r->scheduled_for),$r->execution_input_bytes,new Sha256Hash($r->execution_input_sha256),$r->subscription_version,ReportSubscriptionDeliveryStatus::from($r->status),$r->attempt,$r->run_id,$r->export_id,$r->notification_receipt_id,$r->safe_error_code,$c($r->execution_expires_at),$c($r->retention_delete_after));} }
